/**
 * Copies the Scalar API explorer's browser bundle out of node_modules into public/vendor/, so the
 * api's /docs page loads it from this deployment's own admin origin instead of a third-party CDN:
 * the version is the one the lockfile pins, and no external script ever runs on an origin that
 * holds a session. The copy is regenerated by `dev` and `build` (gitignored), never edited.
 */
import { copyFileSync, mkdirSync, realpathSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const app = join(dirname(fileURLToPath(import.meta.url)), '..');
// The package exports no package.json, so find it through this app's own node_modules link.
const pkg = realpathSync(join(app, 'node_modules', '@scalar', 'api-reference'));
const out = join(app, 'public', 'vendor', 'scalar');
mkdirSync(out, { recursive: true });
copyFileSync(join(pkg, 'dist', 'browser', 'standalone.js'), join(out, 'standalone.js'));
console.log('vendor-scalar: public/vendor/scalar/standalone.js');
